<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>International Greeting</title>
</head>
<body>
  <h1 id="greeting">…loading</h1>

  <script>
    async function fetchJSON(url, payload) {
      const resp = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      return resp.json();
    }

    async function getGreeting() {
      // 1️⃣ Get public IP via a free service (or your own endpoint)
      const { ip } = await fetchJSON("https://api.ipify.org?format=json", {});
      try {
        const { greeting } = await fetchJSON(
          "https://your-function-endpoint/getGreetingByIP",
          { ip }
        );
        return greeting;
      } catch (_) {
        // 2️⃣ Fallback: use navigator.language (e.g., "en-US")
        const { greeting } = await fetchJSON(
          "https://your-function-endpoint/getGreeting",
          { language: navigator.language }
        );
        return greeting;
      }
    }

    // Render
    getGreeting()
      .then(g => document.getElementById("greeting").textContent = g)
      .catch(err => {
        console.error(err);
        document.getElementById("greeting").textContent = "Hello! (fallback)";
      });
  </script>
