### What each block does

| Step | What it does | Why it matters |
|------|--------------|----------------|
| **1️⃣ Detect IP** | Grab the client’s public IP (e.g., `request.ip` on the server, `fetch('https://api.ipify.org?format=json')` in the browser) | The IP is the most reliable proxy for *geographical location* when you don’t have explicit locale data. |
| **2️⃣ Resolve greeting** | Call `getGreetingByIP({ ip })` – the service returns a greeting string that’s already localized for the detected country/region. | No need to maintain your own country‑to‑greeting map; the helper does it for you. |
| **3️⃣ Fallback to language** | If the IP lookup fails (e.g., private network, VPN) or you want a language‑first approach, call `getGreeting({ language })` or `getGreetingWithFormat({ format, language })`. | Guarantees a greeting even when location can’t be determined, and respects the user’s UI language. |
| **4️⃣ Choose format** | `getGreetingWithFormat` can return plain text (`"text"`) or a JSON payload (`"json"`). | Makes it easy to integrate into APIs, templates, or UI components. |

---

## 2️⃣ Ready‑to‑copy code snippets

Below are minimal examples in **Node.js (Express)**, **Python (Flask)**, and **client‑side JavaScript**. Feel free to adapt them to your stack.

### 2.1 Node.js (Express)

```js
// npm install express node-fetch
const express = require('express');
const fetch = require('node-fetch'); // v2 or v3 depending on your Node version
const app = express();
const PORT = 3000;

// Helper that calls the provided function endpoint
async function getGreetingByIP(ip) {
  const res = await fetch('https://your-function-endpoint/getGreetingByIP', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ip })
  });
  const data = await res.json(); // assuming the function returns JSON { greeting: "..." }
  return data.greeting;
}

// Fallback: language‑first greeting
async function getGreetingByLang(lang) {
  const res = await fetch('https://your-function-endpoint/getGreeting', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ language: lang })
  });
  const data = await res.json(); // { greeting: "..." }
  return data.greeting;
}

app.get('/', async (req, res) => {
  // 1️⃣ Grab IP – Express puts the remote address in req.ip (may need trust‑proxy)
  const ip = req.headers['x-forwarded-for']?.split(',')[0]?.trim() || req.ip;

  try {
    const greeting = await getGreetingByIP(ip);
    res.send(`<h1>${greeting} 👋</h1>`);
  } catch (e) {
    // 2️⃣ Fallback to Accept‑Language header
    const lang = req.headers['accept-language']?.split(',')[0] || 'en';
    const greeting = await getGreetingByLang(lang);
    res.send(`<h1>${greeting} 👋</h1>`);
  }
});

app.listen(PORT, () => console.log(`Server listening on http://localhost:${PORT}`));
```

> **Tip:** If you’re behind a reverse proxy (NGINX, Cloudflare, etc.) set `app.set('trust proxy', true)` so `req.ip` reflects the real client IP.

---

### 2.2 Python (Flask)

```python
# pip install flask requests
from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

FUNC_BASE = "https://your-function-endpoint"

def get_greeting_by_ip(ip):
    r = requests.post(f"{FUNC_BASE}/getGreetingByIP", json={"ip": ip})
    r.raise_for_status()
    return r.json()["greeting"]

def get_greeting_by_lang(lang):
    r = requests.post(f"{FUNC_BASE}/getGreeting", json={"language": lang})
    r.raise_for_status()
    return r.json()["greeting"]

@app.route("/")
def index():
    # 1️⃣ Get client IP (Flask's request.remote_addr may be the proxy)
    ip = request.headers.get("X-Forwarded-For", request.remote_addr)

    try:
        greeting = get_greeting_by_ip(ip)
    except Exception:
        # 2️⃣ Fallback to Accept-Language header
        lang = request.headers.get("Accept-Language", "en").split(",")[0]
        greeting = get_greeting_by_lang(lang)

    return f"<h1>{greeting} 🌍</h1>"

if __name__ == "__main__":
    app.run(debug=True, port=5000)
```

---

### 2.3 Browser / Front‑end (Vanilla JS)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>International Greeting</title>
</head>
<body>
  <h1 id="greeting">…loading</h1>

  <script>
    async function fetchJSON(url, payload) {
      const resp = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      return resp.json();
    }

    async function getGreeting() {
      // 1️⃣ Get public IP via a free service (or your own endpoint)
      const { ip } = await fetchJSON("https://api.ipify.org?format=json", {});
      try {
        const { greeting } = await fetchJSON(
          "https://your-function-endpoint/getGreetingByIP",
          { ip }
        );
        return greeting;
      } catch (_) {
        // 2️⃣ Fallback: use navigator.language (e.g., "en-US")
        const { greeting } = await fetchJSON(
          "https://your-function-endpoint/getGreeting",
          { language: navigator.language }
        );
        return greeting;
      }
    }

    // Render
    getGreeting()
      .then(g => document.getElementById("greeting").textContent = g)
      .catch(err => {
        console.error(err);
        document.getElementById("greeting").textContent = "Hello! (fallback)";
      });
  </script>
</body>
</html>
```

---

## 3️⃣ Optional: Use a specific **output format**

If you need a structured response (e.g., you want the greeting plus the detected locale), call `getGreetingWithFormat`:

```js
// Example: request JSON format
const { greeting, locale } = await fetchJSON(
  "https://your-function-endpoint/getGreetingWithFormat",
  { format: "json", language: "es" }   // language optional – auto‑detect if omitted
);
// greeting => "¡Hola!"
// locale   => "es-ES"
```

The JSON payload typically looks like:

```json
{
  "greeting": "¡Hola!",
  "locale": "es-ES",
  "source": "language"   // or "ip" if it came from the IP lookup
}
```

